<?php
namespace App\Services\Excel\Imports;
use App\Models\ToolMaterial; use App\Models\Unit; use App\Services\Excel\ExcelImportDefinition; use Carbon\Carbon; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Validator;
class ToolMaterialImport implements ExcelImportDefinition {
 public function module():string{return 'tools_materials';} public function requiredHeaders():array{return ['itemtype','name','date'];}
 public function importRow(array $row,int $n):string { $type=$row['itemtype']??null; $d=['item_type'=>$type,'sku'=>$row['sku']??null,'name'=>$row['name']??null,'description'=>$row['description']??null,'date'=>$row['date']??null,'opening_quantity'=>$row['openingquantity']??0,'opening_rate'=>$row['openingrate']??0,'reorder_level'=>$row['reorderlevel']??0,'active_status'=>$row['activestatus']??true]; $v=Validator::make($d,['item_type'=>'required|in:tool,material','name'=>'required|string|max:255','date'=>'required|date','sku'=>'nullable|string|max:100','description'=>'nullable|string|max:1000','opening_quantity'=>'numeric|min:0','opening_rate'=>'numeric|min:0','reorder_level'=>'numeric|min:0','active_status'=>'boolean']); if($v->fails())throw new \InvalidArgumentException('Validation failed: '.implode(' ',$v->errors()->all())); if($type==='material'){ $unit=Unit::where('code',trim((string)($row['unit']??'')))->where('active_status',true)->first(); if(!$unit)throw new \InvalidArgumentException('An active unit code is required for materials.'); $d['unit']=$unit->code; }else $d['unit']='Nos'; $d['date']=Carbon::parse($d['date'])->toDateString(); $d['opening_amount']=round((float)$d['opening_quantity']*(float)$d['opening_rate'],2); $existing=ToolMaterial::where('item_type',$type)->where('name',$d['name'])->when(filled($d['sku']),fn($q)=>$q->where('sku',$d['sku']))->first(); DB::transaction(function()use(&$existing,$d){$existing?$existing->update($d):$existing=ToolMaterial::create($d);}); return $existing->wasRecentlyCreated?'created':'updated'; }
}
